import styled from '@emotion/styled';
import * as Slider from '@radix-ui/react-slider';
import { composeStyles } from 'utils/emotion';

type SliderVisualMode = 'default' | 'inputOnly';

type SliderVisualModeProps = {
  $visualMode?: SliderVisualMode;
};

type SliderThumbVariantProps = SliderVisualModeProps & {
  $visible?: boolean;
};

export const StyledSliderRoot = styled(Slider.Root, {
  shouldForwardProp: (prop) => prop !== '$visualMode',
})<SliderVisualModeProps>(
  composeStyles<SliderVisualModeProps>(
    {
      position: 'relative',
      display: 'flex',
      alignItems: 'center',
      userSelect: 'none',
      touchAction: 'none',
      width: '100%',
      height: '8px',
      borderRadius: '64px',
    },
    {
      $visualMode: {
        default: {},
        inputOnly: {
          position: 'absolute',
          top: '50%',
          left: 0,
          transform: 'translateY(-50%)',
          width: '100%',
          height: '20px',
          zIndex: 5,
        },
      },
    },
  ),
);

export const StyledSliderTrack = styled(Slider.Track, {
  shouldForwardProp: (prop) => prop !== '$visualMode',
})<SliderVisualModeProps>(
  composeStyles<SliderVisualModeProps>(
    {
      position: 'relative',
      flexGrow: 1,
      borderRadius: '9999px',
      height: '8px',
    },
    {
      $visualMode: {
        default: {},
        inputOnly: {
          opacity: 0,
        },
      },
    },
  ),
);

export const StyledSliderRange = styled(Slider.Range)({
  position: 'absolute',
  background: '#006EDB',
  borderRadius: '9999px',
  height: '100%',
});

export const StyledSliderThumb = styled(Slider.Thumb, {
  shouldForwardProp: (prop) => prop !== '$visualMode' && prop !== '$visible',
})<SliderThumbVariantProps>(
  composeStyles<SliderThumbVariantProps>(
    {
      display: 'block',
      width: '16px',
      height: '16px',
      background: '#006EDB',
      boxShadow: '0 1px 5px black',
      borderRadius: '50%',
      border: '2px solid white',
      outline: 'none',
      cursor: 'pointer',

      '&:hover': {
        transform: 'scale(1.2)',
        background: '#006EDB',
        border: '2px solid white',
      },

      '&:active': {
        background: '#006EDB',
        transform: 'scale(1.2)',
        border: '2px solid white',
      },

      '&:focus-visible': {
        background: '#006EDB',
        border: '2px solid white',
      },
    },
    {
      $visualMode: {
        default: {
          opacity: 1,
          pointerEvents: 'auto',
        },
        inputOnly: {
          opacity: 0,
          pointerEvents: 'none',
        },
      },
      $visible: {
        true: {},
        false: {
          opacity: 0,
        },
      },
    },
  ),
);
